use affine_cipher::*;

use affine_cipher::AffineCipherError::NotCoprime;

#[test]
fn encode_yes() {
    let phrase = "yes";
    let (a, b) = (5, 7);
    let output = encode(phrase, a, b);
    let expected = Ok("xbt".into());
    assert_eq!(output, expected);
}

#[test]
#[ignore]
fn encode_no() {
    let phrase = "no";
    let (a, b) = (15, 18);
    let output = encode(phrase, a, b);
    let expected = Ok("fu".into());
    assert_eq!(output, expected);
}

#[test]
#[ignore]
fn encode_omg() {
    let phrase = "OMG";
    let (a, b) = (21, 3);
    let output = encode(phrase, a, b);
    let expected = Ok("lvz".into());
    assert_eq!(output, expected);
}

