}

#[test]
#[ignore]
fn encode_all_the_letters() {
    let phrase = "The quick brown fox jumps over the lazy dog.";
    let (a, b) = (17, 33);
    let output = encode(phrase, a, b);
    let expected = Ok("swxtj npvyk lruol iejdc blaxk swxmh qzglf".into());
